/* 第一章《三角形》材料整理：尺规、测距与专题。 */
TID("t07","1.4","尺规作图与作图依据","尺规作三角形常见三类：已知三边；已知两角及其夹边；已知两边及其夹角。作图依据分别对应 SSS、ASA、SAS 的唯一性。","先画一条给定边或一个给定角，再用圆规截取边长、用直尺连接交点；保留作图痕迹并说明所得三角形满足条件。","已知三边作图前必须满足三边关系；无刻度直尺不能用来量长度。",
 Q("作图题","已知三条线段 a、b、c，且任意两边之和大于第三边。写出尺规作 △ABC，使 AB=c、AC=b、BC=a 的步骤。","先作 AB=c，再以 A、B 为圆心分别以 b、a 为半径作弧交于 C，连接 AC、BC",["作线段 AB=c。","以 A 为圆心、b 为半径作弧；以 B 为圆心、a 为半径作弧，两弧交于 C。","连接 AC、BC，所得 △ABC 即为所求。"],[]),
 Q("作图题","已知 ∠α、∠β 和线段 c，写出作 △ABC，使 ∠A=α、∠B=β、AB=c 的基本步骤。","先作 AB=c，再分别在 A、B 处作给定角，两射线交于 C",["作线段 AB=c。","在 A 点作与 AB 构成的角等于 α；在 B 点作与 BA 构成的角等于 β。","两条射线交于 C，连接得到 △ABC。"],[]),
 Q("作图题","已知线段 a、c 和 ∠α，写出作 △ABC，使 BC=a、AB=c、∠ABC=α 的步骤。","作 ∠EBF=α，在两边分别截取 BC=a、BA=c，连接 AC",["作 ∠EBF=α。","在一条射线上截取 BA=c，在另一条射线上截取 BC=a。","连接 AC，得到所求 △ABC。"],[]),
 Q("解答题","为什么“已知三边作三角形”时，要先保证任意两条给定线段之和大于第三条？","保证两圆弧能形成非退化交点，从而三条线段能组成三角形",["三角形必须满足任意两边之和大于第三边。","若两边之和等于或小于第三边，则三点共线或无法连接成非退化三角形。","因此三边作图前必须先满足三边关系。"],[]));

TID("c1-09","1.5","利用全等测量不可达距离","利用全等三角形可以把难以直接测量的线段转化为可直接测量的对应边；关键是构造两个全等三角形，依据是对应边相等。","先明确目标距离属于哪个三角形，再通过中点、平行、垂直、对顶角等条件证明两个三角形全等，最后测量其对应边。","测量结论依赖构造条件，不能只根据示意图认为两段相等。",
 Q("解答题","利用三角形全等测量不能直接测量的两点距离时，核心思路和最终依据分别是什么？","构造两个全等三角形；利用全等三角形对应边相等",["把不可直接测量的目标线段放在一个三角形中。","在可到达位置构造另一个与之全等的三角形。","由对应边相等，把目标距离转化为可测对应边。"],[]),
 Q("证明题","A、B 位于池塘两端，D 为池塘旁一点，C 是 BD 的中点。A、C、E 共线且 CE=CA。证明测量 DE 就能得到 AB。","AB=DE",["C 是 BD 中点，所以 BC=CD；又 AC=CE。","∠BCA=∠DCE（对顶角）。","△ACB≌△ECD（SAS），所以 AB=DE。"],[]),
 Q("解答题","要测量池塘沿岸 A、E 两点距离。取 AB∥CD 且 AB=CD，E 是 BC 的中点。只测 DE 是否可行？说明理由。","可行，AE=DE",["AB∥CD，所以 ∠ABE=∠DCE。","E 是 BC 中点，所以 BE=CE；又 AB=CD。","△AEB≌△DEC（SAS），因此 AE=DE。"],[]),
 Q("解答题","拐尺中 O 是 AB 中点，CA⊥AB、BD⊥AB 且 CA=BD。测房间深度时，使 AC 与内壁方向重合，并在 BD 延长线上找 F，使 F、O 与房间另一端 E 共线。说明为什么量 DF 就得到房间深度 CE。","CE=DF",["CA⊥AB、BD⊥AB，所以相关直角相等；O 是 AB 中点，AO=BO。","利用对顶角，可证 △BOF≌△AOE（ASA），因此 BF=AE。","又 CA=BD，所以 AE−AC=BF−BD，即 CE=DF。"],[]));

TID("c1-10","1.0","角平分线与高线模型","同一顶点处同时出现角平分线与高线时，可用三角形内角和、直角三角形两锐角互余和角平分线把目标角分解。角平分线还常与垂线配合构造全等。","先算顶角，再利用角平分线取一半；高线提供 90°。若另作垂线与高平行，可把顶点处角关系转移到其他位置。","角平分线与高线的位置不同，不能把“平分角”和“垂直底边”混为同一性质。",
 Q("解答题","△ABC 中，AE 是 ∠BAC 的角平分线，AD 是 BC 边上的高，∠C=40°，∠B=70°，DF⊥AE 于 F。（1）求 ∠CAE；（2）求 ∠ADF。","（1）35°；（2）75°",["∠BAC=180°−70°−40°=70°，AE 平分 ∠BAC，所以 ∠CAE=35°。","AD⊥BC，在 Rt△ACD 中，∠CAD=90°−40°=50°。","∠DAE=50°−35°=15°；DF⊥AE，所以 ∠ADF=90°−15°=75°。"],[]),
 Q("解答题","△ABC 中，AE 平分 ∠BAC，AD⊥BC。（1）若 ∠C=70°、∠B=30°，求 ∠DAE；（2）F 在 AE 上，FG⊥BC，若 ∠B=40°、∠C=80°，求 ∠EFG；（3）若 F 在 AE 延长线上，∠EFG 是否改变？","（1）20°；（2）20°；（3）不改变，仍为20°",["（1）∠BAD=60°，∠BAC=80°，∠BAE=40°，所以 ∠DAE=20°。","（2）AD⊥BC、FG⊥BC，所以 AD∥FG；∠BAC=60°，∠BAE=30°，∠BAD=50°，得 ∠EAD=20°，所以 ∠EFG=20°。","（3）平行关系不变，∠EFG 仍等于 ∠EAD=20°。"],[]),
 Q("证明题","Rt△ABC 中，∠BAC=90°，AB=AC，BE 平分 ∠ABC 交 AC 于 D，且 CE⊥BE。证明 BD=2CE。","BD=2CE",["延长 CE 与 BA 的延长线交于 F。由 BE 平分 ∠ABC，且 ∠BEF=∠BEC=90°，可证 △BEF≌△BEC（ASA），故 EF=CE，CF=2CE。","由直角三角形中的余角关系得 ∠ABD=∠ACF；结合 AB=AC、∠BAD=∠CAF，可证 △ABD≌△ACF（ASA）。","因此 BD=CF=2CE。"],[]),
 Q("证明题","AD∥BC，D、E、C 共线，AE、BE 分别平分 ∠DAB、∠CBA。证明 DE=CE。","DE=CE",["由 AD∥BC，∠DAB+∠ABC=180°；两角平分后可得 ∠AEB=90°。","延长 AE 交 BC 延长线于 F，可证 △ABE≌△FBE（ASA），得到 AE=FE。","再由 AD∥BC 得相应等角，结合对顶角，可证 △ADE≌△FCE（ASA）。","所以 DE=CE。"],[]));

TID("c1-11","1.0","平移、轴对称与旋转全等模型","平移、翻折、旋转不改变图形的形状和大小，因此变换前后的对应三角形全等。平移模型常通过平行线找等角，轴对称模型常有公共边，旋转模型常用角的和差得到夹角相等。","先识别图形变换类型，再寻找“不变量”：平移保平行与长度，轴对称保距离与角，旋转保长度和旋转角。","模型只是帮助识别关系，正式证明仍应写出具体的 SSS、SAS、ASA 或 AAS 条件。",
 Q("证明题","A、B、C、D 共线，AB=CD，DE∥AF 且 DE=AF。证明 △AFC≌△DEB；若 △DEB 沿 AD 方向平移到另外两个位置，条件不变时是否仍全等？","均全等，均可用 SAS",["由 AB=CD，按不同位置利用加、减公共线段可得 AC=BD。","DE∥AF，所以 ∠A=∠D；且 AF=DE。","因此 △AFC≌△DEB（SAS）。","平移后上述等边、等角关系仍成立，所以仍全等。"],[]),
 Q("证明题","四边形 ACBD 中，P 在对角线 AB 上，连接 PC、PD。已知 ∠APD=∠CPA，∠DBP=∠PBC。（1）证明 △BDP≌△BCP；（2）证明 AD=AC。","（1）△BDP≌△BCP（ASA）；（2）AD=AC",["∠APD 与 ∠DPB 互补，∠CPA 与 ∠CPB 互补；由 ∠APD=∠CPA，得 ∠DPB=∠CPB。","PB 为公共边，且 ∠DBP=∠PBC，所以 △BDP≌△BCP（ASA）。","由全等得 DP=CP。在 △ADP 和 △ACP 中，AP 公共、∠APD=∠CPA、DP=CP，所以两三角形 SAS 全等，得 AD=AC。"],[]),
 Q("证明题","在“风筝”图案中，AB=AD，AC=AE，且 ∠BAE=∠DAC。证明 ∠E=∠C。","∠E=∠C",["由 ∠BAE=∠DAC，两边同加公共角 ∠EAC，得 ∠CAB=∠EAD。","在 △ABC 和 △ADE 中，AB=AD、AC=AE、∠CAB=∠EAD。","所以 △ABC≌△ADE（SAS），对应角 ∠C=∠E。"],[]),
 Q("证明题","在 △ABC 和 △AED 中，AB=AE，AC=AD，且 ∠BAE=∠CAD。证明 △ABC≌△AED。","△ABC≌△AED（SAS）",["由 ∠BAE=∠CAD，两边同加公共角 ∠CAE，得 ∠BAC=∠EAD。","AB=AE、AC=AD。","因此 △ABC≌△AED（SAS）。"],[]));
